referenceSolutions.python:
def risingLabelsEvenKeyCensus(readings):
    a=readings
    out=[]
    from bisect import bisect_left
    tails=[]
    for x in a:
        i=bisect_left(tails,x)
        if i==len(tails): tails.append(x)
        else: tails[i]=x
        out.append(i+1)
    return sum(x%2==0 for x in out)

